# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
#
# gcu400 tuning (2026-11-13, L600, bench kernel mode do_bench median
# w1000/r100, core shapes 512^3..4096^3):
#   - the generic host upcast every fp16/bf16 call to fp32 (3 aten _to_copy
#     kernels) before the mm kernels and cast the results back (2 more), and
#     materialised both operand transposes via .contiguous() (2 aten copy
#     kernels). At 4096^3 fp16 that path measured 4663us; the fp32 GEMM pair
#     alone is 4395us of it.
#   - the Triton mm kernel takes strides (NT layout flows straight into the
#     kernel: no transpose copy), and it accumulates in fp32
#     (dot_out_dtype=tl.float32), so skipping the host upcast is
#     precision-neutral for the 2-D path: fp16 products are exact in fp32 and
#     the single output rounding is the same one the upcast path performs.
#   - saturated 2-D GEMMs (>= 2^29 MACs, the same line gcu400 bmm uses for
#     its own native delegation) run on the captured native primo++ pipeline
#     via the batch-1 bmm entry, which accepts the NT/transposed views with
#     zero copies; below the line the Triton mm kernel is faster
#     (launch-bound segment).
# Measured (2 GEMMs, us @ 512^3/1024^3/2048^3/4096^3):
#   fp16 128.4/148.0/698.5/4662.9 -> 15.0/40.8/134.1/948.2
#   fp32  34.4/122.8/636.0/4496.8 -> 26.5/80.4/448.9/3585.8
# The batched path keeps the generic fp32-upcast semantics (broadcast
# reductions in fp16 lose precision; no measured workload pays for the risk).
import logging

import torch

from .sum import sum_dim

logger = logging.getLogger(__name__)

# 2-D GEMMs at or above this many multiply-accumulates run faster on the native
# pipeline. Re-measured on 2026-11-18 (bench do_bench median, sum of 2 GEMMs):
#   fp32 2048^3 Triton mm 648us vs native bmm 925~980us (native 1.5x slower)
#   fp32 4096^3 native 4376us vs Triton mm 8326us (native 1.9x faster)
# The crossover lies between 2048^3 (8.6e9 MAC) and 4096^3 (6.9e10 MAC), so raise the threshold from 2^29 to
# 2^34, letting 2048^3 use Triton mm while 4096^3 still uses native.
_2D_NATIVE_DELEGATE_WORK = 1 << 34

# The backend may replace mm/bmm only after import, so keep lazy resolution; but cache the result
# to avoid going through the import machinery on every forward (for small shapes like 512^3 this accounts for over 30%
# of wall-clock time).
_MM_BMM_CACHE = None


def _lookup_matmul_entries():
    """The mm / bmm entries off the flag_gems namespace, resolved at call time.

    Why: a backend may override mm with a kernel whose tune configs carry keys
    the general kernel does not declare -- kunlunxin's mm takes SPLIT_K and the
    general one does not -- so importing flag_gems.ops.mm directly binds the
    general kernel and the backend's own configs then fail with
    "Keyword argument SPLIT_K was specified but unrecognised". Same reasoning
    as _matmul() in linalg_matrix_power.py.

    Returns:
        The (mm, bmm) callables for the active backend.
    """
    global _MM_BMM_CACHE
    if _MM_BMM_CACHE is None:
        from flag_gems import bmm, mm

        _MM_BMM_CACHE = (mm, bmm)
    return _MM_BMM_CACHE


def _matmul_2d_or_batched(a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
    """Matrix multiply using the Triton mm/bmm kernels.

    Both ``a`` and ``b`` have their contracting dimension as the last two
    dims (``(..., M, K)`` and ``(..., K, N)``). Leading batch dimensions are
    broadcast against each other, mirroring ``torch.matmul``.
    """
    if a.dim() == 2 and b.dim() == 2:
        mm, bmm = _lookup_matmul_entries()
        M, K = a.shape
        N = b.shape[1]
        if M * N * K >= _2D_NATIVE_DELEGATE_WORK:
            # Batch-1 views: bmm routes saturated GEMMs to the captured
            # native kernel, which takes arbitrary strides (the NT operand
            # views need no transpose-copy materialisation).
            return bmm(a.unsqueeze(0), b.unsqueeze(0)).squeeze(0)
        # Strides (including NT transposed views) flow straight into the
        # Triton kernel; do not materialise transposes with .contiguous().
        return mm(a, b)

    M, K = a.shape[-2], a.shape[-1]
    K2, N = b.shape[-2], b.shape[-1]
    batch_shape = torch.broadcast_shapes(a.shape[:-2], b.shape[:-2])

    a_exp = a.expand(*batch_shape, M, K).reshape(-1, M, K).contiguous()
    b_exp = b.expand(*batch_shape, K2, N).reshape(-1, K2, N).contiguous()
    _, bmm = _lookup_matmul_entries()
    out = bmm(a_exp, b_exp)
    return out.reshape(*batch_shape, M, N)


def _sum_to(grad: torch.Tensor, shape) -> torch.Tensor:
    """Reduce ``grad`` (a broadcasted gradient) back to ``shape`` via summation."""
    shape = tuple(shape)
    while grad.dim() > len(shape):
        grad = sum_dim(grad, dim=[0], keepdim=False)
    for i in range(len(shape)):
        if shape[i] == 1 and grad.shape[i] != 1:
            grad = sum_dim(grad, dim=[i], keepdim=True)
    return grad


def matmul_backward(
    grad: torch.Tensor,
    self: torch.Tensor,
    other: torch.Tensor,
    mask,
):
    """Backward pass for ``torch.matmul``.

    Given ``out = matmul(self, other)`` and the upstream gradient ``grad``,
    returns ``(grad_self, grad_other)``. Each is ``None`` when the
    corresponding entry of ``mask`` is False.
    """
    logger.debug("GEMS_ENFLAME MATMUL_BACKWARD")

    need_self, need_other = bool(mask[0]), bool(mask[1])

    dim_self = self.dim()
    dim_other = other.dim()

    # 2-D x 2-D (1-D operands fold up to 2-D) takes the fast path: the Triton
    # mm / native kernels accumulate in fp32, so fp16/bf16 inputs keep full
    # accumulation precision without any host upcast. The batched path below
    # still chains broadcast reductions, where fp16/bf16 partial sums lose
    # precision, so it keeps the fp32-upcast semantics.
    two_d = dim_self <= 2 and dim_other <= 2

    compute_dtype = self.dtype
    if not two_d and self.dtype in (torch.float16, torch.bfloat16):
        compute_dtype = torch.float32

    s = self.to(compute_dtype) if self.dtype != compute_dtype else self
    o = other.to(compute_dtype) if other.dtype != compute_dtype else other
    g = grad.to(compute_dtype) if grad.dtype != compute_dtype else grad

    # Fold 1D operands up to 2D, mirroring how torch.matmul treats vectors:
    # a 1D `self` becomes (1, K) and a 1D `other` becomes (K, 1). The folded
    # dimensions are dropped from the forward output, so they must be inserted
    # back into `grad` before computing the gradients.
    folded_self = dim_self == 1
    folded_other = dim_other == 1

    if folded_self:
        s = s.unsqueeze(-2)
    if folded_other:
        o = o.unsqueeze(-1)

    if folded_other:
        g = g.unsqueeze(-1)
    if folded_self:
        g = g.unsqueeze(-2)

    grad_self = None
    grad_other = None

    if need_self:
        # grad_self = grad @ other^T
        gs = _matmul_2d_or_batched(g, o.transpose(-2, -1))
        gs = _sum_to(gs, s.shape)
        if folded_self:
            gs = gs.squeeze(-2)
        grad_self = gs.to(self.dtype) if gs.dtype != self.dtype else gs

    if need_other:
        # grad_other = self^T @ grad
        go = _matmul_2d_or_batched(s.transpose(-2, -1), g)
        go = _sum_to(go, o.shape)
        if folded_other:
            go = go.squeeze(-1)
        grad_other = go.to(other.dtype) if go.dtype != other.dtype else go

    return grad_self, grad_other
